--                       INFORMATIKA, AZERBAYCAN TARIXI
--
--  BU FAYL ELLE YAZILMIR - tools/sinif9.py yaradir:
--      python3 tools/sinif9.py
--
--  Az dili 8 + Ingilis dili 6 + Informatika 5 + Tarix 6
--  az/ing/tarix 20 movzu x 30 + inf 5 movzu x 20 = 700.
--  ext_key: az9-/ing9-/inf9-/tarix9-...
--  ON SERT: 41_movzular_orta9.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where (s.slug, t.slug) in (('az-dili','az-9-tabeli-qurulus'),
                                ('ingilis-dili','ing-9-books'),
                                ('informatika','inf-9-cedvel'),
                                ('tarix','tarix-9-cumhuriyyet'))
     having count(*) = 4) then
    raise exception 'ONCE 41_movzular_orta9.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and (q.ext_key like 'az9-%' or q.ext_key like 'ing9-%'
        or q.ext_key like 'inf9-%' or q.ext_key like 'tarix9-%');

